            $snombre = trim($snombre);
            $papellido = trim($papellido);
            $sapellido = trim($sapellido);
            //*******************************************************************************
            $interesado = null;
            if ($crearInteresado) {
                $interesado = !empty($nuid) ? InteresadosPeer::getInteresadoByNuid($nuid) : null;
            } elseif (!empty($pnombre) || !empty($papellido)) {
