            }
            //*******************************************************************************
            if ($interesado != null) {
                return $interesado;
            }
            //*******************************************************************************
            //CIUDAD_INTERESADO en la plantilla trae el codigo DANE, no el nombre.
            $ciudad = CiudadPeer::getCiudadByNombAndCod(null, trim($ciudadCodigo), true);
