                'NUMERO_IDENTIFICACION' => $nuid,
                'TIPO_IDENTIFICACION' => $tipoidentificacion_id,
                'CIUDAD_ID' => $ciudad != null ? $ciudad->getPrimaryKey() : null,
                'EMAIL' => trim($email),
                'USUARIO_ID' => $usuario_id
            );
            //*******************************************************************************
