            $object = new Interesados();
            $anterior_object = clone $object;
            //****************************************************************************
            $object->setPrimerNombre(utf8_encode(trim($info_data['PRIMER_NOMBRE'])));
            $object->setPrimerApellido(utf8_encode(trim($info_data['PRIMER_APELLIDO'])));
