            $object->setTipoidentificacionId(isset($info_data['TIPO_IDENTIFICACION']) ? trim($info_data['TIPO_IDENTIFICACION']) : $tnuid_default);
            $object->setTipogeneroId(isset($info_data['TIPO_GENERO']) ? trim($info_data['TIPO_GENERO']) : $tgenero_default);
            $object->setCiudadId(trim($info_data['CIUDAD_ID']));
            $object->setNumeroIdentificacion(trim($info_data['NUMERO_IDENTIFICACION']));
            $object->setDireccion(isset($info_data['DIRECCION']) ? utf8_encode(trim($info_data['DIRECCION'])) : null);
